// Mock data for the busyness scaffold. Only queries.ts imports this file;
// it goes away once the check-ins tables exist.
//
// The JSON files in mock/ are generated by scripts/generate-busyness-mock.ts
// (`npm run mock:busyness`). Pick a scenario with MOCK_BUSYNESS_SCENARIO in .env,
// or `none` for real check-ins only. Pages label generated data (#64).
import busy from "./mock/busy.json";
import moderate from "./mock/moderate.json";
import quiet from "./mock/quiet.json";
import week from "./mock/week.json";
import type { CheckIn, Climber } from "./types";

// Shape of a scenario file. Timestamps are ISO strings in JSON.
export type MockScenario = {
  scenario: string;
  // The mock "now". Every timestamp is fixed relative to it.
  referenceTime: string;
  climbers: Climber[];
  checkIns: (Omit<CheckIn, "timestamp"> & { timestamp: string })[];
};

// Typical climbers in the gym per weekday (Mon first) and hour.
export type MockWeek = {
  gymId: string;
  startHour: number;
  endHour: number;
  days: string[];
  values: number[][];
};

const SCENARIOS = { quiet, moderate, busy } as Record<string, MockScenario>;
export const MOCK_SCENARIO_NAMES = Object.keys(SCENARIOS);
const DEFAULT_SCENARIO = "moderate";

// null for `none`: no generated check-ins, only real ones.
function currentScenario(): MockScenario | null {
  const name = process.env.MOCK_BUSYNESS_SCENARIO ?? DEFAULT_SCENARIO;
  if (name === "none") return null;
  return SCENARIOS[name] ?? SCENARIOS[DEFAULT_SCENARIO];
}

// The clock the mock data was built around. Fixed, so results are the same
// on every request. With no scenario, the real clock.
export function mockNow(): Date {
  const scenario = currentScenario();
  return scenario ? new Date(scenario.referenceTime) : new Date();
}

export function mockClimbers(): Climber[] {
  return currentScenario()?.climbers ?? [];
}

export function mockCheckIns(): CheckIn[] {
  return (currentScenario()?.checkIns ?? []).map((c) => ({
    ...c,
    timestamp: new Date(c.timestamp),
  }));
}

export function mockWeek(): MockWeek {
  return week;
}
